export type Ball = { x: number; y: number; vx: number; vy: number; r: number; color: string };

const COLORS = ["#e11d48", "#2563eb", "#16a34a", "#f59e0b", "#9333ea", "#0891b2", "#db2777"];

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

export function makeBall(w: number, h: number, existing: Ball[] = []): Ball {
  const r = 10;
  let x = rand(r, w - r);
  let y = rand(r, h - r);
  for (let tries = 0; tries < 50; tries++) {
    const overlaps = existing.some((b) => Math.hypot(b.x - x, b.y - y) < b.r + r);
    if (!overlaps) break;
    x = rand(r, w - r);
    y = rand(r, h - r);
  }
  return {
    x,
    y,
    vx: rand(-3, 3),
    vy: rand(-3, 3),
    r,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

export function makeBalls(n: number, w: number, h: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(makeBall(w, h, balls));
  return balls;
}

function clamp(b: Ball, w: number, h: number): void {
  if (b.x - b.r < 0) {
    b.x = b.r;
    b.vx = Math.abs(b.vx);
  } else if (b.x + b.r > w) {
    b.x = w - b.r;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y - b.r < 0) {
    b.y = b.r;
    b.vy = Math.abs(b.vy);
  } else if (b.y + b.r > h) {
    b.y = h - b.r;
    b.vy = -Math.abs(b.vy);
  }
}

export function step(balls: Ball[], w: number, h: number): void {
  for (const b of balls) {
    b.vy += 0.2;
    b.x += b.vx;
    b.y += b.vy;
    clamp(b, w, h);
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.hypot(dx, dy);
      const min = a.r + b.r;
      if (dist < min) {
        const nx = dist === 0 ? 1 : dx / dist;
        const ny = dist === 0 ? 0 : dy / dist;
        const approaching = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny < 0;
        if (approaching) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
        const overlap = (min - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        clamp(a, w, h);
        clamp(b, w, h);
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement, balls: Ball[]): void {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
  }
}

