use "./sim.ts" { makeBall, makeBalls, step, draw }

const W = 400
const H = 300

page Home "/" {
  ref box
  ref balls
  ref raf
  state count = 0
  state frames = 0
  state paused = false

  fn loop() {
    if paused { return }
    step(balls, W, H)
    draw(box, balls)
    frames++
    raf = requestAnimationFrame(loop)
  }

  fn start() {
    cancelAnimationFrame(raf)
    raf = requestAnimationFrame(loop)
  }

  fn add() {
    balls.push(makeBall(W, H, balls))
    count = balls.length
    draw(box, balls)
  }

  fn toggle() {
    if paused {
      paused = false
      start()
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  fn reset() {
    balls = makeBalls(5, W, H)
    count = balls.length
    frames = 0
    draw(box, balls)
  }

  mount {
    balls = makeBalls(5, W, H)
    count = balls.length
    draw(box, balls)
    start()
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 align=start {
    title "Simulación de pelotas"
    canvas id="sim" ref=box width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${count}`
      text `Cuadros: ${frames}`
    }
  }
}

use "./sim.ts" { createSim }

page Home "/" {
  state paused = false
  state count = 5
  state frames = 0
  computed label = paused ? "Reanudar" : "Pausar"
  ref box
  ref sim

  mount {
    sim = createSim(box, (n, f) => {
      count = n
      frames = f
    })
    cleanup { sim.destroy() }
  }

  fn toggle() {
    paused = !paused
    sim.setPaused(paused)
  }

  column gap=4 pad=4 align=start {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc; background: #fff"
    row gap=2 {
      button "Agregar" primary -> sim.add()
      button label -> toggle()
      button "Reiniciar" -> sim.reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

