type Ball = { x: number; y: number; vx: number; vy: number; color: string };

const R = 10;
const GRAVITY = 0.2;
const COLORS = ["#e11d48", "#2563eb", "#16a34a", "#f59e0b", "#9333ea", "#0891b2", "#db2777"];

export function createSim(
  canvas: HTMLCanvasElement,
  onFrame: (balls: number, frames: number) => void
) {
  const ctx = canvas.getContext("2d")!;
  const W = canvas.width;
  const H = canvas.height;
  let balls: Ball[] = [];
  let frames = 0;
  let paused = false;
  let rafId: number | null = null;

  function makeBall(): Ball {
    let x = 0;
    let y = 0;
    for (let tries = 0; tries < 50; tries++) {
      x = R + Math.random() * (W - 2 * R);
      y = R + Math.random() * (H - 2 * R);
      const ok = balls.every((b) => Math.hypot(b.x - x, b.y - y) >= 2 * R);
      if (ok) break;
    }
    return {
      x,
      y,
      vx: (Math.random() * 2 - 1) * 4,
      vy: (Math.random() * 2 - 1) * 4,
      color: COLORS[Math.floor(Math.random() * COLORS.length)],
    };
  }

  function step() {
    for (const b of balls) {
      b.vy += GRAVITY;
      b.x += b.vx;
      b.y += b.vy;
      if (b.x < R) {
        b.x = R;
        b.vx = Math.abs(b.vx);
      } else if (b.x > W - R) {
        b.x = W - R;
        b.vx = -Math.abs(b.vx);
      }
      if (b.y < R) {
        b.y = R;
        b.vy = Math.abs(b.vy);
      } else if (b.y > H - R) {
        b.y = H - R;
        b.vy = -Math.abs(b.vy);
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const dist = Math.hypot(dx, dy);
        if (dist < 2 * R) {
          const nx = dist === 0 ? 1 : dx / dist;
          const ny = dist === 0 ? 0 : dy / dist;
          const approaching = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny < 0;
          if (approaching) {
            const tvx = a.vx;
            const tvy = a.vy;
            a.vx = b.vx;
            a.vy = b.vy;
            b.vx = tvx;
            b.vy = tvy;
          }
          const overlap = (2 * R - dist) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          b.x += nx * overlap;
          b.y += ny * overlap;
          for (const c of [a, b]) {
            c.x = Math.min(W - R, Math.max(R, c.x));
            c.y = Math.min(H - R, Math.max(R, c.y));
          }
        }
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
    }
  }

  function loop() {
    step();
    draw();
    frames++;
    onFrame(balls.length, frames);
    rafId = requestAnimationFrame(loop);
  }

  function start() {
    if (rafId === null && !paused) rafId = requestAnimationFrame(loop);
  }

  function stop() {
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  }

  function reset() {
    balls = [];
    for (let i = 0; i < 5; i++) balls.push(makeBall());
    frames = 0;
    draw();
    onFrame(balls.length, frames);
  }

  reset();
  start();

  return {
    add() {
      balls.push(makeBall());
      if (paused) draw();
      onFrame(balls.length, frames);
    },
    reset() {
      reset();
    },
    setPaused(p: boolean) {
      paused = p;
      if (p) stop();
      else start();
    },
    destroy() {
      stop();
    },
  };
}

