fn formatDate(iso) {
  let [y, m, d] = iso.split("-")
  return `${d}/${m}/${y}`
}

fn formatUSD(n) {
  let digits = String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ".")
  return `US$ ${digits}`
}

fn initials(name) {
  return name
    .split(" ")
    .filter(p => p != "")
    .slice(0, 2)
    .map(p => p[0].toUpperCase())
    .join("")
}

fn colorFor(name) {
  let hash = 0
  for (let i = 0; i < name.length; i++) {
    hash = (hash * 31 + name.charCodeAt(i)) | 0
  }
  let hue = Math.abs(hash) % 360
  return `hsl(${hue}, 60%, 45%)`
}

fn place(t) {
  return `${t.city}, ${t.country}`
}

