// ─────────────────────────────────────────────
// Modelo
// ─────────────────────────────────────────────

model Traveler {
  id: Number
  name: String
  country: String
  city: String
  arrival: String
  budget: Number
}

// ─────────────────────────────────────────────
// Datos de ejemplo
// ─────────────────────────────────────────────

const TRAVELERS = [
  { id: 1, name: "Ana Rojas", country: "Perú", city: "Lima", arrival: "2026-03-12", budget: 1200 },
  { id: 2, name: "Bruno Díaz", country: "México", city: "Oaxaca", arrival: "2026-01-05", budget: 850 },
  { id: 3, name: "Carla Gómez", country: "Perú", city: "Cusco", arrival: "2026-02-20", budget: 2300 },
  { id: 4, name: "Diego Silva", country: "Chile", city: "Valparaíso", arrival: "2026-04-02", budget: 640 },
  { id: 5, name: "Elena Ruiz", country: "México", city: "Mérida", arrival: "2026-03-01", budget: 1500 },
  { id: 6, name: "Facundo Paz", country: "Argentina", city: "Salta", arrival: "2026-02-11", budget: 990 },
  { id: 7, name: "Gabriela Luna", country: "Chile", city: "Santiago", arrival: "2026-01-28", budget: 1750 },
  { id: 8, name: "Hugo Vera", country: "Argentina", city: "Mendoza", arrival: "2026-03-30", budget: 1100 }
]

const COUNTRIES = ["Todos", "Argentina", "Chile", "México", "Perú"]

// ─────────────────────────────────────────────
// Utilidades de formato
// ─────────────────────────────────────────────

fn formatDate(iso) {
  let [y, m, d] = iso.split("-")
  return `${d}/${m}/${y}`
}

fn formatUSD(n) {
  let s = Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".")
  return `US$ ${s}`
}

fn initials(name) {
  return name.split(" ").filter(w => w.length > 0).map(w => w[0]).join("").toUpperCase()
}

fn colorFor(name) {
  let h = 0
  for (let i = 0; i < name.length; i++) {
    h = (h * 31 + name.charCodeAt(i)) >>> 0
  }
  return `hsl(${h % 360}, 60%, 45%)`
}

fn place(t) {
  return `${t.city}, ${t.country}`
}

fn sortByArrival(list) {
  return [...list].sort((a, b) => a.arrival.localeCompare(b.arrival))
}

// ─────────────────────────────────────────────
// Componentes
// ─────────────────────────────────────────────

component Avatar(name: String) {
  row align=center justify=center class="avatar" style=(`background:${colorFor(name)}`) aria-hidden="true" {
    text initials(name) bold
  }

  style {
    .avatar {
      width: 44px;
      height: 44px;
      min-width: 44px;
      border-radius: 50%;
      color: #fff;
    }
  }
}

component TravelerRow(t: Traveler) {
  card pad=3 {
    row gap=3 align=center {
      Avatar name=t.name
      column gap=1 {
        link t.name to=(`/viajero/${t.id}`)
        text place(t) muted
        text `Llega el ${formatDate(t.arrival)}` small
      }
      text formatUSD(t.budget) bold class="budget"
    }
  }

  style {
    .budget {
      margin-left: auto;
    }
  }
}

// ─────────────────────────────────────────────
// Páginas
// ─────────────────────────────────────────────

page Home "/" {
  meta title="Viajeros"

  state country = "Todos"
  computed visible = sortByArrival(TRAVELERS.filter(t => country == "Todos" || t.country == country))

  column gap=4 pad=4 {
    title "Viajeros" tag=h1
    text `${visible.length} viajeros` muted
    select country options=COUNTRIES label="País"
    column gap=2 {
      for t in visible key t.id {
        TravelerRow t=t
      }
    }
  }
}

page TravelerDetail "/viajero/:id" {
  computed traveler = TRAVELERS.find(t => String(t.id) == params.id)

  column gap=3 pad=4 {
    if traveler {
      row gap=3 align=center {
        Avatar name=traveler.name
        title traveler.name tag=h1
      }
      text place(traveler)
      text `Llega el ${formatDate(traveler.arrival)}`
      text `Presupuesto: ${formatUSD(traveler.budget)}`
    } else {
      title "Viajero no encontrado" tag=h1
    }
    link "Volver" to="/"
  }
}

page NotFound "*" {
  column gap=3 pad=4 {
    title "Página no encontrada" tag=h1
